    // leptonica: pixMorphDwa_2 (dwacomb.2.c)
    /// <summary>Adds a border, does the dwa operation and removes the border.</summary>
    /// <param name="pixd">usual 3 choices: null, == pixs, != pixs</param>
    /// <param name="pixs">1 bpp</param>
    /// <param name="operation">L_MORPH_DILATE, L_MORPH_ERODE, L_MORPH_OPEN, L_MORPH_CLOSE</param>
    /// <param name="selname">name of the sel</param>
    /// <returns>pixd</returns>
    /// <remarks>
    /// (1) This simply adds a border, calls the appropriate
    ///     pixFMorphopGen_*(), and removes the border.
    ///     See the notes for that function.
    /// (2) The size of the border depends on the operation
    ///     and the boundary conditions.
    /// </remarks>
    public static Pix MorphDwa_2(Pix? pixd, Pix pixs, int operation, string selname)
    {
        int bordersize;
        uint bordercolor;
        Pix pixt1, pixt2, pixt3;

        const string func = "pixMorphDwa_2";

        if (pixs.Depth != 1)
            throw Lept.Arg(func, "pixs must be 1 bpp");

            /* Set the border size */
        bordercolor = GetMorphBorderPixelColor(L.L_MORPH_ERODE, 1);
        bordersize = 32;
        if (bordercolor == 0 && operation == L.L_MORPH_CLOSE)
            bordersize += 32;

        pixt1 = pixs.AddBorder(bordersize, 0);
        pixt2 = FMorphopGen_2(null, pixt1, operation, selname);
        pixt3 = pixt2.RemoveBorder(bordersize);

        if (pixd == null)
            return pixt3;

        Copy(pixd, pixt3);
        return pixd;
    }

    // leptonica: pixFMorphopGen_2 (dwacomb.2.c)
    /// <summary>Dwa morphological operation with a generated sel.</summary>
    /// <param name="pixd">usual 3 choices: null, == pixs, != pixs</param>
    /// <param name="pixs">1 bpp</param>
    /// <param name="operation">L_MORPH_DILATE, L_MORPH_ERODE, L_MORPH_OPEN, L_MORPH_CLOSE</param>
    /// <param name="selname">name of the sel</param>
    /// <returns>pixd</returns>
    /// <remarks>
    /// (1) This is a dwa operation, and the Sels must be limited in
    ///     size to not more than 31 pixels about the origin.
    /// (2) A border of appropriate size (32 pixels, or 64 pixels
    ///     for safe closing with asymmetric b.c.) must be added before
    ///     this function is called.
    /// (3) This handles all required setting of the border pixels
    ///     before erosion and dilation.
    /// (4) The closing operation is safe; no pixels can be removed
    ///     near the boundary.
    /// </remarks>
    public static unsafe Pix FMorphopGen_2(Pix? pixd, Pix pixs, int operation, string selname)
    {
        int index, w, h, wpls, wpld, erodeop, borderop;
        uint bordercolor;
        Pix pixt;

        const string func = "pixFMorphopGen_2";

        if (pixs.Depth != 1)
            throw Lept.Arg(func, "pixs must be 1 bpp");

            /* Get boundary colors to use */
        bordercolor = GetMorphBorderPixelColor(L.L_MORPH_ERODE, 1);
        if (bordercolor == 1)
            erodeop = L.PIX_SET;
        else
            erodeop = L.PIX_CLR;

        if (!SelNames.SEL_INDEX.TryGetValue(selname, out index))
            throw Lept.Arg(func, "sel index not found");
        index <<= 1;

        if (pixd == null)
            pixd = CreateTemplate(pixs);
        else  /* for in-place or pre-allocated */
            pixd.ResizeImageData(pixs);
        wpls = pixs.Wpl;
        wpld = pixd.Wpl;

            /* The images must be surrounded, in advance, with a border of
             * size 32 pixels (or 64, for closing), that we'll read from.
             * Fabricate a "proper" image as the subimage within the 32
             * pixel border, having the following parameters:  */
        w = pixs.Width - 64;
        h = pixs.Height - 64;
        fixed (uint* ps = pixs.Data, pd = pixd.Data) {
            uint* datas = ps + 32 * wpls + 1;
            uint* datad = pd + 32 * wpld + 1;

            if (operation == L.L_MORPH_DILATE || operation == L.L_MORPH_ERODE) {
                borderop = L.PIX_CLR;
                if (operation == L.L_MORPH_ERODE) {
                    borderop = erodeop;
                    index++;
                }
                if (pixd == pixs) {  /* in-place; generate a temp image */
                    pixt = Copy(null, pixs);
                    fixed (uint* pt = pixt.Data) {
                        uint* datat = pt + 32 * wpls + 1;
                        pixt.SetOrClearBorder(32, 32, 32, 32, borderop);
                        DwaLow.fmorphopgen_low_2(datad, w, h, wpld, datat, wpls, index);
                    }
                }
                else { /* not in-place */
                    pixs.SetOrClearBorder(32, 32, 32, 32, borderop);
                        DwaLow.fmorphopgen_low_2(datad, w, h, wpld, datas, wpls, index);
                }
            }
            else {  /* opening or closing; generate a temp image */
                pixt = CreateTemplate(pixs);
                fixed (uint* pt = pixt.Data) {
                    uint* datat = pt + 32 * wpls + 1;
                    if (operation == L.L_MORPH_OPEN) {
                        pixs.SetOrClearBorder(32, 32, 32, 32, erodeop);
                        DwaLow.fmorphopgen_low_2(datat, w, h, wpls, datas, wpls, index + 1);
                        pixt.SetOrClearBorder(32, 32, 32, 32, L.PIX_CLR);
                        DwaLow.fmorphopgen_low_2(datad, w, h, wpld, datat, wpls, index);
                    }
                    else {  /* closing */
                        pixs.SetOrClearBorder(32, 32, 32, 32, L.PIX_CLR);
                        DwaLow.fmorphopgen_low_2(datat, w, h, wpls, datas, wpls, index);
                        pixt.SetOrClearBorder(32, 32, 32, 32, erodeop);
                        DwaLow.fmorphopgen_low_2(datad, w, h, wpld, datat, wpls, index + 1);
                    }
                }
            }
        }

        return pixd;
    }
